INSERT INTO feature VALUES('kernel-readmission','kernel','Independent kernel readmission','kernel-admission','implemented','notable',NULL,'Each declaration the checker accepts is re-derived by the kernel in a fresh environment before it is exported. A deep handler is re-derived as the fold of its effect''s free model, a data declaration of one constructor per operation admitted ahead of its first handler. A capability scope the one model in scope answers crosses with that model''s components filled in, the same definition as the scope naming it.','core-checker kernel-core','crates/core-checker-base/tests/recursive_data.rs crates/surface-corpus/src/kernel_export.rs corpus/model/effects/state-handler.gandr','corpus/model/effects/state-handler.gandr',NULL);
